def decrypt_and_run():
    """Decrypt and execute the main application"""
    try:
        # Decode and decompress
        compressed = base64.b64decode(ENCRYPTED_PAYLOAD.strip())
        code = zlib.decompress(compressed)
        
        # Execute the decrypted code
        exec(code, {'__name__': '__main__', '__file__': __file__})
    except Exception as e:
        print(f"Failed to decrypt application: {e}")
        sys.exit(1)

if __name__ == "__main__":
    decrypt_and_run()
